#!/usr/bin/env bash
# Self-contained CSS для board-game/close-preview-round (bash-only).
set -euo pipefail

ROUND="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
THEME="$(cd "$ROUND/.." && pwd)"
OUT="$ROUND/lab-base.css"
SOURCES=("$THEME/styles.css" "$THEME/logic-round/styles.css" "$THEME/hybrid-round/styles.css" "$THEME/screens-round/styles.css" "$THEME/frames-round/styles.css")

{
  cat <<'HDR'
/* Auto-generated by sync-lab.sh - do not edit by hand */
/* Round: board-game/close-preview-round */
/* Sources: board-game/styles.css + logic/hybrid/screens/frames-round (канон BG-1…BG-3) */

HDR
  for src in "${SOURCES[@]}"; do
    if [[ ! -f "$src" ]]; then
      echo "sync-lab.sh: missing source: $src" >&2
      exit 1
    fi
    cat "$src"
    printf '\n'
  done
} > "$OUT"

echo "OK: $OUT"
